/usr/bin/bash -lc "PYTHONPATH=source python - <<'PY'
import itertools, warnings
import numpy as np, torch
from monai.metrics import compute_surface_dice
rng=np.random.default_rng(8)
for ndim in (2,3):
 for trial in range(15):
  shape=tuple(rng.integers(3,8,size=ndim)); p=rng.random(shape)<.35;g=rng.random(shape)<.35
  sp=tuple(rng.uniform(.2,5,size=ndim));t=float(rng.uniform(0,5))
  with warnings.catch_warnings():
   warnings.simplefilter('ignore')
   def sc(a,b,s):return compute_surface_dice(torch.tensor(a)[None,None],torch.tensor(b)[None,None],[t],True,spacing=s).item()
   base=sc(p,g,sp);swap=sc(g,p,sp)
   if not (0<=base<=1 and abs(base-swap)<1e-6):raise RuntimeError((ndim,trial,base,swap))
   for perm in itertools.permutations(range(ndim)):
    got=sc(p.transpose(perm),g.transpose(perm),tuple(sp[i] for i in perm))
    if abs(base-got)>2e-6:raise RuntimeError(('perm',ndim,trial,perm,base,got))
print('random symmetry/range/axis checks passed')
PY"
